import { useState } from 'react';
import { SidebarNav } from '@/components/SidebarNav';
import { DashboardHeader } from '@/components/DashboardHeader';
import { StatsGrid } from '@/components/StatsGrid';
import { LayoutDashboard, Users, BarChart2, Settings, FileText } from 'lucide-react';

export default function App() {
  const [collapsed, setCollapsed] = useState(false);

  const navItems = [
    { label: 'Dashboard', icon: <LayoutDashboard className="h-4 w-4" />, active: true },
    { label: 'Users',     icon: <Users className="h-4 w-4" />, badge: 12 },
    { label: 'Reports',   icon: <BarChart2 className="h-4 w-4" /> },
    { label: 'Documents', icon: <FileText className="h-4 w-4" /> },
    { label: 'Settings',  icon: <Settings className="h-4 w-4" /> },
  ];

  return (
    <div className="flex h-screen bg-slate-50 font-sans">
      <SidebarNav
        brandName="Acme"
        items={navItems}
        collapsed={collapsed}
        onToggleCollapse={() => setCollapsed(c => !c)}
      />
      <div className="flex flex-col flex-1 overflow-hidden">
        <DashboardHeader
          brandName="Acme"
          pageTitle="Dashboard"
          userEmail="admin@acme.com"
          userInitials="AD"
          notificationCount={3}
        />
        <main className="flex-1 overflow-y-auto p-6">
          <h2 className="text-xl font-semibold text-slate-800 mb-4">Overview</h2>
          <StatsGrid />
        </main>
      </div>
    </div>
  );
}

/components/SidebarNav.tsx.content:
import { cn } from '@/lib/utils';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface NavItem {
  label: string;
  icon: React.ReactNode;
  href?: string;
  active?: boolean;
  badge?: string | number;
}

interface SidebarNavProps {
  items: NavItem[];
  collapsed?: boolean;
  onToggleCollapse?: () => void;
  brandName?: string;
  brandLogo?: React.ReactNode;
}

export function SidebarNav({ items, collapsed = false, onToggleCollapse, brandName }: SidebarNavProps) {
  return (
    <aside
      className={cn(
        'flex flex-col bg-slate-900 text-slate-100 transition-all duration-300 relative',
        collapsed ? 'w-16' : 'w-56'
      )}
    >
      {/* Brand */}
      <div className={cn('flex items-center h-14 px-4 border-b border-slate-700 font-bold text-lg tracking-tight', collapsed && 'justify-center')}>
        {!collapsed && <span>{brandName}</span>}
        {collapsed && <span className="text-violet-400">A</span>}
      </div>

      {/* Nav items */}
      <nav className="flex-1 py-4 space-y-0.5">
        {items.map((item) => (
          <button
            key={item.label}
            className={cn(
              'w-full flex items-center gap-3 px-4 py-2.5 text-sm transition-colors rounded-none',
              item.active
                ? 'bg-violet-600 text-white'
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-100',
              collapsed && 'justify-center px-2'
            )}
          >
            {item.icon}
            {!collapsed && <span className="flex-1 text-left">{item.label}</span>}
            {!collapsed && item.badge !== undefined && (
              <span className="ml-auto text-xs bg-violet-500/20 text-violet-300 px-1.5 py-0.5 rounded-full">{item.badge}</span>
            )}
          </button>
        ))}
      </nav>

      {/* Collapse toggle */}
      <button
        onClick={onToggleCollapse}
        className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-6 rounded-full bg-slate-700 border border-slate-600 flex items-center justify-center text-slate-300 hover:bg-slate-600 transition-colors z-10"
        aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
      >
        {collapsed ? <ChevronRight className="h-3 w-3" /> : <ChevronLeft className="h-3 w-3" />}
      </button>
    </aside>
  );
}

/components/DashboardHeader.tsx.content:
import { Bell, Search } from 'lucide-react';

interface DashboardHeaderProps {
  brandName: string;
  pageTitle?: string;
  userEmail?: string;
  userInitials?: string;
  notificationCount?: number;
  onSearch?: (q: string) => void;
}

export function DashboardHeader({ pageTitle, userInitials = 'U', notificationCount = 0 }: DashboardHeaderProps) {
  return (
    <header className="h-14 border-b border-slate-200 bg-white px-6 flex items-center justify-between flex-shrink-0">
      <h1 className="text-base font-semibold text-slate-800">{pageTitle}</h1>
      <div className="flex items-center gap-3">
        {/* Search */}
        <div className="relative">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-400" />
          <input
            type="text"
            placeholder="Search…"
            className="h-8 w-48 pl-8 pr-3 text-sm rounded-lg bg-slate-100 border border-transparent focus:border-violet-300 focus:bg-white focus:outline-none transition-all"
          />
        </div>
        {/* Notifications */}
        <button className="relative p-1.5 rounded-lg hover:bg-slate-100 transition-colors" aria-label="Notifications">
          <Bell className="h-4 w-4 text-slate-500" />
          {notificationCount > 0 && (
            <span className="absolute top-0 right-0 w-4 h-4 text-[10px] font-bold bg-violet-600 text-white rounded-full flex items-center justify-center">
              {notificationCount}
            </span>
          )}
        </button>
        {/* Avatar */}
        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-violet-500 to-fuchsia-500 flex items-center justify-center text-white text-xs font-semibold">
          {userInitials}
        </div>
      </div>
    </header>
  );
}

