import { TrendingUp, Users, DollarSign, Activity } from 'lucide-react';

const stats = [
  { label: 'Total Revenue', value: '$45,231', change: '+20.1%', positive: true, icon: DollarSign, color: 'from-violet-500 to-fuchsia-500' },
  { label: 'Active Users',  value: '2,350',   change: '+15.3%', positive: true, icon: Users,       color: 'from-sky-500 to-blue-500' },
  { label: 'New Signups',   value: '1,247',   change: '+8.2%',  positive: true, icon: TrendingUp,  color: 'from-emerald-400 to-teal-500' },
  { label: 'Churn Rate',    value: '2.4%',    change: '-0.4%',  positive: true, icon: Activity,    color: 'from-orange-400 to-rose-500' },
];

export function StatsGrid() {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
      {stats.map((s) => (
        <div key={s.label} className="bg-white rounded-2xl p-5 shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-3">
            <span className="text-sm font-medium text-slate-500">{s.label}</span>
            <div className={`w-9 h-9 rounded-xl bg-gradient-to-br ${s.color} flex items-center justify-center`}>
              <s.icon className="h-4 w-4 text-white" />
            </div>
          </div>
          <p className="text-2xl font-bold text-slate-800">{s.value}</p>
          <p className={`text-xs mt-1 font-medium ${s.positive ? 'text-emerald-600' : 'text-rose-500'}`}>{s.change} from last month</p>
        </div>
      ))}
    </div>
  );
}
